from bisect import bisect_left

def findWordsNotInSubsequence(s, t):
    # 每个字母在 t 中出现的位置列表，总大小 O(|t|)，比 |t|×26 的跳表省内存
    pos = {}
    for i, c in enumerate(t):
        pos.setdefault(c, []).append(i)

    def is_subseq(w):
        cur = 0                              # 下一次匹配必须从 t[cur] 开始找
        for c in w:
            lst = pos.get(c)
            if not lst:
                return False
            k = bisect_left(lst, cur)
            if k == len(lst):
                return False
            cur = lst[k] + 1
        return True

    return [w for w in s.split() if not is_subseq(w)]
